Minimal server example (TypeScript):
// src/index.ts
import { Server } from "@modelcontextprotocol/sdk/server/index.js";
import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";

const server = new Server(
  { name: "trace-storage", version: "0.1.0" },
  { capabilities: { tools: {} } }
);

server.setRequestHandler("tools/list", async () => ({
  tools: [{
    name: "search_traces",
    description: "Search traces by service and time range",
    inputSchema: {
      type: "object",
      properties: {
        service: { type: "string" },
        since: { type: "string", format: "date-time" }
      },
      required: ["service"]
    }
  }]
}));

server.setRequestHandler("tools/call", async (req) => ({
  content: [{ type: "text", text: `stub: ${JSON.stringify(req.params)}` }]
}));

const transport = new StdioServerTransport();
await server.connect(transport);

Example (HTTP variant):
// HTTP variant
import express from "express";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";

const app = express();
app.use((req, res, next) => {
  const token = req.headers.authorization?.replace("Bearer ", "");
  if (!verifyToken(token)) return res.status(401).end();
  next();
});

app.get("/health", (_, res) => res.json({ ok: true }));

app.all("/mcp", async (req, res) => {
  const transport = new StreamableHTTPServerTransport({
    sessionIdGenerator: () => crypto.randomUUID()
  });
  await server.connect(transport);
  await transport.handleRequest(req, res);
});

app.listen(3000);

