diff_runs.py:
```python
import json, sys

base = {r["id"]: r for r in (json.loads(l) for l in open(sys.argv[1]))}
new = {r["id"]: r for r in (json.loads(l) for l in open(sys.argv[2]))}

regressed, improved = [], []
for id, n in new.items():
    b = base.get(id)
    if b and n["score"] - b["score"] <= -0.2:
        regressed.append((id, b["score"], n["score"]))
    elif b and n["score"] - b["score"] >= 0.2:
        improved.append((id, b["score"], n["score"]))

print(f"## Eval diff\n\n- improved: {len(improved)}\n- regressed: {len(regressed)}\n")
if regressed:
    print("### Regressions\n| id | before | after |\n|---|---|---|")
    for id, b, n in regressed:
        print(f"| {id} | {b:.2f} | {n:.2f} |")
    sys.exit(1)
```
